  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Thiết lập CuaDriver trên máy chủ môi trường chạy này. CuaDriver quản lý quyền của hệ điều hành; Dovo kết nối agent thông qua MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Tên hoặc đường dẫn tệp thực thi trên máy chủ, không có dấu ngoặc kép của shell. Phần ghi đè của agent được ưu tiên. Terminal mới sẽ dùng cài đặt shell này.',
