  'Enable agent computer use on this computer':
    'Bật tính năng sử dụng máy tính cho agent trên máy tính này',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Cấp cho agent có quyền ghi quyền truy cập màn hình máy tính này. Agent chỉ đọc không được áp dụng. Người dùng và agent dùng chung màn hình và trạng thái ứng dụng.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Để trống Cua Driver để tự tìm trong PATH hoặc thư mục cài đặt tiêu chuẩn trên máy tính này. Thay đổi áp dụng cho lượt chạy agent mới.',
  '1. Install on this computer': '1. Cài đặt trên máy tính này',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Chạy trình cài đặt chính thức trên máy chủ môi trường chạy, rồi làm mới trạng thái. Trình cài đặt sẽ tải xuống và cài đặt CuaDriver; không cần tài khoản Cua.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Hệ thống Linux tối giản cần libxi6 và at-spi2-core. GNOME cần tiện ích WinRects đi kèm Cua; xem hướng dẫn cài đặt.',
  'Install and set up Cua Driver': 'Cài đặt và thiết lập Cua Driver',
  'Detect / check Cua Driver': 'Phát hiện / kiểm tra Cua Driver',
  '2. Permissions & desktop access': '2. Quyền và truy cập màn hình',
  '3. Agent MCP, skills & hooks': '3. MCP, kỹ năng và hook của agent',
  '4. Computer History (optional preview)': '4. Computer History (bản xem trước tùy chọn)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Cấp quyền Trợ năng và Ghi màn hình cho CuaDriver trên macOS rồi chấp nhận khởi chạy lại. Kiểm tra quyền truy cập màn hình sẽ liệt kê ứng dụng mà không thay đổi chúng. Các nút điều khiển daemon ảnh hưởng đến phiên sử dụng máy tính đang hoạt động.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Lưu công tắc sử dụng máy tính để tự động bật dovo_cua MCP trong các lượt mới của agent có quyền ghi. Không cần đăng ký MCP thủ công. Cài gói kỹ năng chính thức tùy chọn; quá trình cài đặt sẽ liên kết với các agent được phát hiện trên máy tính này.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Lịch sử chỉ chứa siêu dữ liệu, được mã hóa và chỉ ghi khi bạn chọn tham gia. Bật có thể khởi động lại daemon. Tắt không xóa dữ liệu đã ghi; tạm dừng sẽ ngừng ghi trong thời gian ngắn. Bản dựng không hỗ trợ sẽ báo lỗi. Dữ liệu vẫn trên máy chủ môi trường chạy; Xem lịch sử gần đây sẽ tải tối đa 20 sự kiện tại đây.',
  'Delete recorded Computer History?': 'Xóa Computer History đã ghi?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Xóa toàn bộ lịch sử đã ghi và khóa mã hóa của lịch sử đó trên máy tính này. Không thể hoàn tác.',
