  'Suggest a next prompt after a Claude or Codex turn. Tap the suggestion to insert it without sending. On desktop, press Tab to insert it or Escape to dismiss it. Each suggestion makes an extra model request and uses plan usage.':
    'Gợi ý câu lệnh tiếp theo sau lượt Claude hoặc Codex. Chạm vào gợi ý để chèn mà không gửi. Trên máy tính, nhấn Tab để chèn hoặc Escape để bỏ qua. Mỗi gợi ý tạo thêm một yêu cầu mô hình và sử dụng hạn mức gói.',
  'Scheduled worker capacity': 'Sức chứa worker theo lịch',
  'Scheduled jobs wait at this threshold. One slot stays available for conversation work. Direct messages and needed children can exceed it. Running work is kept.':
    'Các công việc theo lịch sẽ chờ khi đạt ngưỡng này. Một vị trí luôn được giữ lại cho công việc hội thoại. Tin nhắn trực tiếp và các công việc con cần thiết có thể vượt ngưỡng. Công việc đang chạy được giữ nguyên.',
  'Continue interrupted turns after runtime restart':
    'Tiếp tục các lượt bị gián đoạn sau khi khởi động lại môi trường chạy',
  'Interrupted turns can resume automatically. Queued messages stay paused until you resume them. Stopped tasks and automations still require Retry.':
    'Các lượt bị gián đoạn có thể tự động tiếp tục. Tin nhắn trong hàng đợi vẫn tạm dừng cho đến khi bạn tiếp tục. Tác vụ và tự động hóa đã dừng vẫn cần Thử lại.',
  'Auto-archive inactive tasks': 'Tự động lưu trữ tác vụ không hoạt động',
  Never: 'Không bao giờ',
  'After 7 days': 'Sau 7 ngày',
  'After 14 days': 'Sau 14 ngày',
  'After 30 days': 'Sau 30 ngày',
  'Computer fallback when no scoped archiving rule is set. Scoped On archives after time in Settled; scoped Off disables automatic archiving. Running, waiting, pinned tasks and open terminals are protected.':
    'Phương án dự phòng của máy tính khi không có quy tắc lưu trữ theo phạm vi. Bật theo phạm vi sẽ lưu trữ sau thời gian ở trạng thái Đã ổn định; tắt theo phạm vi sẽ vô hiệu hóa lưu trữ tự động. Tác vụ đang chạy, đang chờ, được ghim và thiết bị đầu cuối đang mở sẽ được bảo vệ.',
  'Keep this computer awake while tasks run': 'Giữ máy tính này luôn thức khi tác vụ đang chạy',
  'macOS only. Prevents idle sleep while a task is working, so it keeps going while you follow it here.':
    'Chỉ dành cho macOS. Ngăn máy tính ngủ khi không hoạt động trong lúc tác vụ đang chạy, để tác vụ tiếp tục khi bạn theo dõi tại đây.',
  'Model modes (experimental)': 'Chế độ mô hình (thử nghiệm)',
  'Tune & Maestro modes (experimental)': 'Chế độ Tune và Maestro (thử nghiệm)',
  'Tune chooses a model within the default agent. Maestro chooses the agent and model together. Both choose reasoning once before the first turn. Inherit keeps project defaults.':
    'Tune chọn mô hình trong agent mặc định. Maestro chọn cả agent lẫn mô hình. Cả hai chọn mức suy luận một lần trước lượt đầu tiên. Kế thừa sẽ giữ mặc định của dự án.',
