  'Use custom TURN': 'Dùng TURN tùy chỉnh',
  'Use automatic relay': 'Dùng relay tự động',
  'Relay fallback': 'Relay dự phòng',
  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'Máy tính phải cho phép relay trong mã QR ghép đôi. Với ghép đôi chỉ dùng Direct, hãy tạo mã QR mới có bật Dovo trên máy tính và ghép đôi lại.',
  'Scan pairing QR code': 'Quét mã QR ghép đôi',
  'Point your camera at the QR code shown by Dovo Studio or the server’s pair command.':
    'Hướng camera vào mã QR do Dovo Studio hoặc lệnh ghép đôi của máy chủ hiển thị.',
  'Allow camera access to scan a pairing code. You can also enter the address and code manually.':
    'Cho phép truy cập camera để quét mã ghép đôi. Bạn cũng có thể nhập địa chỉ và mã thủ công.',
