  'Connect your phone': 'Kết nối điện thoại',
  'Scan the QR code in this app to connect over the internet. No VPN or local IP needed. You can also pair using a LAN / VPN address.':
    'Quét mã QR trong ứng dụng này để kết nối qua internet. Không cần VPN hoặc IP cục bộ. Bạn cũng có thể ghép đôi bằng địa chỉ LAN / VPN.',
  'Internet connection': 'Kết nối internet',
