  'Discard action': 'Hủy thao tác',
  'Discard this action?': 'Hủy thao tác này?',
  'Unsent work will be removed from this phone. Actions already applied on the computer remain applied.':
    'Công việc chưa gửi sẽ bị xóa khỏi điện thoại này. Các thao tác đã áp dụng trên máy tính vẫn được giữ nguyên.',
