    'Quyền truy cập máy tính này đã được khôi phục. Một số thao tác đã lưu có thể đã chạy và việc thử lại có thể khiến chúng lặp lại. Kiểm tra máy tính trước khi tiếp tục. Tin nhắn giữ nguyên danh tính gửi ban đầu.',
