  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Ghép đôi lại',
  'Connection stages': 'Các bước kết nối',
  'Start your computer': 'Khởi động máy tính',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Mở Dovo trên máy tính và giữ cho máy luôn thức. Trong Cài đặt → Thiết bị & môi trường chạy, đăng nhập và bật Dovo Connect. Đăng nhập cùng tài khoản trên điện thoại rồi chọn Connect. Không cần mã ghép đôi, VPN hoặc IP cục bộ để truy cập internet.',
  'Direct internet connection': 'Kết nối internet trực tiếp',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN kết nối trực tiếp điện thoại với máy tính. Nội dung của bạn được mã hóa đầu cuối. Bật Dovo Connect cho phép chuyển tiếp dự phòng được mã hóa nếu mạng chặn kết nối trực tiếp. Relay chuyển tiếp lưu lượng đã mã hóa; không thể đọc nội dung của bạn.',
  'LAN / VPN connections': 'Kết nối LAN / VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Ghép đôi LAN / VPN riêng để ưu tiên kết nối đó khi khả dụng. Sao chép toàn bộ địa chỉ Wi-Fi, Tailscale, NetBird hoặc HTTPS hiển thị trên máy tính, bao gồm cả cổng. localhost và 0.0.0.0 không phải là địa chỉ mà điện thoại có thể kết nối.',
  'Check your network': 'Kiểm tra mạng',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Dùng cùng mạng Wi-Fi hoặc kết nối cả hai thiết bị với VPN. Với kết nối Wi-Fi, hãy cho phép Dovo truy cập Mạng cục bộ trong Cài đặt iPhone.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Mã ghép đôi hết hạn sau hai phút. Mã CLI được phê duyệt tự động; mã từ máy tính có thể cần được phê duyệt tại đó.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Bạn đã lưu ghép đôi. Hãy thử Kết nối lại trước khi tạo mã khác. Nếu địa chỉ đã thay đổi, hãy chọn Cập nhật địa chỉ kết nối trong cài đặt của máy tính này.',
